function flFile(which){const files={tax:'export function roundTax(cents: number) {\n  return Math.round(cents);\n}',test:'it("保留整数分", () => {\n  expect(roundTax(123)).toBe(123);\n});',readme:'# 账单中心\n金额使用整数分，税额边界需单独验证。'};document.getElementById('fl-file-preview').textContent=files[which];}
function flMemory(k){return card('记忆统计',flKv([['有效经验','1 / 500'],['有效规则','1 / 100'],['待审规则','1'],['今日写入','2 / 20']]))+card('记忆条目',`<div class="row wrap"><span class="chip on">账单中心</span><span class="badge">EXPERIENCE · 经验</span><span class="badge b-primary">RULE · 规则</span></div>${['金额边界应使用整数分','导出必须验证角色权限'].map((t,n)=>`<div class="sep"></div><div class="row wrap"><b>${t}</b>${S(flState.memory[k+n]?'CANCELLED':'PASSED',flState.memory[k+n]?'已撤销':'有效')}<span class="badge ${n?'b-primary':''}">${n?'RULE':'EXPERIENCE'}</span></div><p>${n?'财务导出需检查当前角色，避免复用过期授权。':'税额计算先转换为整数分，覆盖零值和半分边界。'}</p><p class="muted small">账单中心 · 使用 ${n?3:8} 次 · 最近使用今天 09:18 · 到期：${n?'长期有效':'180 天后'} · 风险标记：无</p><details><summary>写入审计与出处</summary><p>09:10 · ${flPersonName(k)} 写入 → ${n?'09:15 · Morgan 批准 RULE':'经验自动生效'} · 审计 MA-${n+21}</p><a href="#/executions">出处执行 · BIL-139</a></details>${flBtn('撤销',`flRevokeMemory('${k}',${n})`,'danger sm',!!flState.memory[k+n],'条目已撤销')}`).join('')}`)+card('记忆与权限','<div class="note info">规则记忆审批仅限有 memory_approve 的人类；记忆不能授予角色或委托。</div>'+flBtn('在知识库中打开',"go('knowledge')"));}
function flPersonName(k){return PEOPLE[k].n;}
function flRevokeMemory(k,n){openModal(card('撤销记忆',`<div class="note danger">该记忆将立即停止后续注入；历史执行保留原有引用。需重新认证（原型演示）。</div><p>受影响执行：BIL-139、BIL-142。你需要检查已有证据与结论。</p>${flBtn('取消','closeModal()')}${flBtn('模拟认证并撤销',`flConfirmMemory('${k}',${n})`,'danger')}`));}
function flConfirmMemory(k,n){flState.memory[k+n]=true;closeModal();document.getElementById('fl-agent-body').innerHTML=flMemory(k);flIcons();toast('已撤销；受影响的执行 2 个（演示）');}
function flAdopt(k){openModal(card('收编 '+PEOPLE[k].n,`<p>收编后由你独立管理，不再受原编制授权到期影响；不会自动获得裁决委托。</p>${flBtn('取消','closeModal()')}${flBtn('确认收编',`flConfirmAdopt('${k}')`,'primary')}`));}
function flConfirmAdopt(k){flState.agents[k]={...flState.agents[k],adopted:true};closeModal();route();toast('已收编（演示）');}
function flRetire(k){openModal(card('退役检查',`<div class="note danger">退役会转交或释放在途工作、清理工作目录并吊销凭证。强制退役会取消执行，未保存状态可能丢失且无法撤销；需重新认证。</div>${flKv([['在途工作',WI.filter(w=>w.who===k&&w.s!=='ACCEPTED').length+' 项'],['交接文档','需生成并检查'],['接手人','尚未选择'],['主管的项目',k==='lead'?'账单中心、商户控制台；退役后切回人工确认':'无']])}<p class="muted small">本页仅提供退役检查，完整交接向导未接入。</p>${flBtn('关闭','closeModal()')}${flBtn('开始退役','', 'danger',true,'先完成交接文档和接手人选择')}`));}
