PAGES['heavy']=(id)=>{if(id!=='BIL-139')return head('并行求解','报告不存在','请选择 BIL-139。');return head('账单中心 · BIL-139','Heavy 并行求解对比报告','触发：高风险税额边界返工 · 截止剩余 18 分钟。',S(flState.heavy?'AGENT_CLAIMED_DONE':'PENDING',flState.heavy==='abandon'?'全部已放弃':flState.heavy?'已声明完成（未验证）':'待选择'))+card('预算',`<div class="row wrap"><b>${money(6.8)} / ${money(10)}</b><span class="muted">剩余 ${money(3.2)} · 三枝成本与工作项一致</span></div><div class="progress"><i style="width:68%"></i></div>`)+`<div class="grid g12">${flBranches.map((b,n)=>`<div class="c4">${card(n===0?'系统排序第 1 · 主管 Agent 推荐':'系统排序第 '+(n+1),who(b.agent)+flKv([['模型',b.model],['执行终态',S('SUCCEEDED')],['证据覆盖',b.coverage],['必需验证',S(b.verify)],['测试结果',b.tests],['diff 规模',b.diff],['成本',money(b.cost)],['时长',b.duration],['验证结论',n===0?'边界样本通过，可送正常裁决':n===1?'半分边界仍无定论':'缺少负税额样本'],['AI 辅助意见','仅参考，不是裁决']])+ (flState.heavy&&flState.heavy!=='synthesis'&&flState.heavy!==b.key?'<div class="note">已归档（保留证据）</div>':'')+flBtn('选这一枝送审',`flHeavyChoice('${b.key}')`,'primary',!!flState.heavy,'计划已处理')+`<details><summary>执行与证据详情</summary><p>独立工作树 · 基线 tax.ts · 证据保留，不自动合并。</p><a href="#/executions">查看执行列表</a></details>`)}</div>`).join('')}</div>`+card('主管 Agent 理由',`<div class="row">${who('lead')}<span class="badge b-info">主管原文</span></div><p>Opus 枝覆盖全部验收边界，变更集中在整数分计算，回归全部通过。建议送审；其余两枝保留供复查，不应直接合并到交付包。</p>`)+card('选择与归档',`<div class="note info">择优或合成后提交声明，仍需正常验证与裁决。落选分支归档保留证据，不计为已接受交付物。</div><div class="row wrap" style="margin-top:12px">${flBtn('合成…',"flHeavyChoice('synthesis')",'',!!flState.heavy,'计划已处理')}${flBtn('全部放弃',"flHeavyChoice('abandon')",'danger',!!flState.heavy,'计划已处理')}</div>`);};
function flHeavyChoice(choice){openModal(card(choice==='abandon'?'全部放弃':choice==='synthesis'?'合成分支':'选枝送审',`${choice==='abandon'?'<div class="note danger">全部分支将归档，已有成本不退回。不会形成完成声明。需重新认证（原型演示）。</div>':choice==='synthesis'?`<p>剩余预算 $3.20；合成执行仍受此预算限制。</p><label>主枝<select id="fl-main">${flBranches.map(b=>`<option value="${b.key}">${b.model}</option>`).join('')}</select></label><p>被合成枝（至少一枝，不能与主枝相同）</p>${flBranches.map(b=>`<label class="row"><input type="checkbox" name="fl-source" value="${b.key}">${b.model}</label>`).join('')}`:'<div class="note info">已提交声明后仍需正常验证与裁决。</div>'}<p><label>理由（必填）<textarea id="fl-choice-reason" oninput="document.getElementById('fl-choice-submit').disabled=!this.value.trim()"></textarea></label></p>${flBtn('取消','closeModal()')}<button id="fl-choice-submit" class="btn ${choice==='abandon'?'danger':'primary'}" disabled onclick="flHeavySubmit('${choice}')">${choice==='abandon'?'模拟认证并全部放弃':'提交声明'}</button>`));}
function flHeavySubmit(choice){if(!document.getElementById('fl-choice-reason').value.trim())return;if(choice==='synthesis'){const main=document.getElementById('fl-main').value,src=Array.from(document.querySelectorAll('input[name="fl-source"]:checked')).map(e=>e.value);if(!src.length||src.includes(main)){toast('请选择至少一个与主枝不同的被合成枝','info');return;}flState.heavy='synthesis';flState.heavyMain=main;flState.heavySources=src;}else flState.heavy=choice;closeModal();route();toast(choice==='abandon'?'分支已归档（演示）':'已提交声明，仍需正常验证与裁决（演示）');}
PAGES['spawn-request']=(id)=>{if(id!=='SR-12')return head('编制授权','请求不存在','请从我的裁决选择自建请求。');const done=flState.request!=='PROPOSED';return head('团队 · 自建请求','SR-12 · 创建 Echo-2','主管 Atlas · 编制授权 SG-3 · 逐个人工审批 · 剩余审批时间 23 小时 51 分钟。',S(done?flState.request==='CREATED'?'PASSED':'CANCELLED':'INCONCLUSIVE',done?flState.request==='CREATED'?'已创建':'已驳回':'待批准'))+`<div class="grid g12"><div class="c6">${card('申请理由',who('lead')+'<p>账单中心积压 4 个文档类工作项，Bo 满载。申请增加一名轻量执行者处理 CSV 接口文档与验收样例，避免占用高强度代码执行槽。</p>')}${card('申请规格',flKv([['名称','Echo-2'],['角色','Agent 执行者'],['机器','build-box'],['运行时 × 模型','Codex · gpt-6-mini'],['推理强度','中'],['技能','billing-review（主管已挂载）'],['MCP','git（主管允许）'],['最大风险','低'],['单 Agent 成本上限','$10.00'],['到期','5 天后']]))}</div><div class="c6">${card('与编制授权逐项校验',flTable(['校验项','申请 / 授权','结果'],[['角色','执行者 / 执行者、协调员',S('PASSED')],['机器','build-box / 已允许',S('PASSED')],['模型与强度','gpt-6-mini · 中 / 已允许',S('PASSED')],['技能子集','billing-review ⊆ 主管技能',S('PASSED')],['MCP 子集','git ⊆ 主管能力',S('PASSED')],['风险','低 / 上限低',S('PASSED')],['单 Agent 成本','$10 / 上限 $10',S('PASSED')],['可执行槽','1 / 1 占用；创建后等待槽',S('INCONCLUSIVE','需等待')]]))}${card('授权用量',flKv([['在岗名额',done&&flState.request==='CREATED'?'3 / 3':'2 / 3'],['今日创建',done&&flState.request==='CREATED'?'2 / 5':'1 / 5'],['累计预算','$18.40 / $50.00'],['剩余预算','$31.60']])+'<div class="progress"><i style="width:36.8%"></i></div><p class="muted small">子 Agent 成本同时计入编制与项目预算；批准时重新校验授权与用量。</p>')}</div><div class="c12">${card('状态时间线',flTable(['时间','状态','主体 / 说明'],[['09:21','已提出','Atlas · SG-3 校验通过'],['09:21','等待人工审批','审批超时 24 小时后自动过期'],...(done?[['刚刚',flState.request==='CREATED'?'已创建':'已驳回','Morgan · '+flEsc(flState.requestReason||'')]]:[])]))}</div><div class="c12">${card('裁决',`<div class="note info">批准需要 agent_manage，无需重新认证。未收编子 Agent 不可接受裁决委托。自动模式下请求只读，显示「已按授权自动创建」。</div><div class="row wrap" style="margin-top:12px">${flBtn('批准',"flSpawnDecision(true)",'primary',done,'仅待批准状态可操作')}${flBtn('驳回',"flSpawnDecision(false)",'danger',done,'请求已处理')}${flBtn('调整授权',"go('policy')")}</div>${flState.request==='CREATED'?'<p class="muted small">Echo-2 已创建（本地演示），等待空闲执行槽；不写入主文件 PEOPLE。</p>':''}`)}</div></div>`;};
function flSpawnDecision(approve){openModal(card(approve?'批准创建 Echo-2':'驳回自建请求',`<p>${approve?'将占用第 3 个编制名额；机器槽位满载，新 Agent 等待空闲槽。无需重新认证。':'请求将结束且不会创建 Agent；驳回理由至少 10 字。'}</p><label>理由<textarea id="fl-spawn-reason" oninput="document.getElementById('fl-spawn-submit').disabled=this.value.trim().length<${approve?1:10}"></textarea></label>${flBtn('取消','closeModal()')}<button id="fl-spawn-submit" class="btn ${approve?'primary':'danger'}" disabled onclick="flSpawnSubmit(${approve})">${approve?'批准':'确认驳回'}</button>`));}
function flSpawnSubmit(approve){const reason=document.getElementById('fl-spawn-reason').value.trim();if(flState.request!=='PROPOSED'||reason.length<(approve?1:10))return;flState.request=approve?'CREATED':'REJECTED';flState.requestReason=reason;closeModal();route();toast(approve?'Echo-2 已创建，等待空闲槽（演示）':'自建请求已驳回（演示）');}
